from collections import defaultdict

def transfer_tubes(n, v, edges):
    remaining_tubes = defaultdict(int)
    for edge in edges:
        remaining_tubes[edge[0]] -= 1
        remaining_tubes[edge[1]] -= 1

    # Check if there's a feasible solution based on the remaining tubes
