        if remaining_tubes[i] >= 1:
            return "NO"
    return "YES"

def find_transfusions(initial, desired, n, v, edges):
    for d in range(v + 1):
        for x, y in edges:
            if (initial[x] + d < v):
                initial[x] += d
            if (initial[y] + d < v):
                initial[y] += d
            if(y == x):
                initial[y] -= d
                initial[x] += d
        if initial == desired:
            return [i for i in range(1, n+1) if initial[i] == desired[i]]
    return []

def print_tubes(k, transfusions, initial, desired):
    for transfusion in transfusions:
        print(f"{transfusion[0]} {transfusion[1]} {transfusion[2]}")
    print(k)

