from collections import defaultdict

def find_pumping_order(n, pipes):
    graph = defaultdict(dict)
    for a, b, flow in pipes:
        graph[a][b] = flow
        graph[b][a] = flow if a != b else 0  # Reverse edge direction

    def max_flow(node, visited):
        queue = []
        visited[node] = True
        max_flow[node] = 0
        max_flow[None] = float('-inf')
        for nxt, capacity in sorted(graph[node].items(), key=lambda x: -x[1]):
            if capacity >= max_flow[None] and not visited[nxt]:
                queue.append([nxt, capacity])
        while queue:
            node, capacity = queue.pop()
            if node is None:
                for nxt, capacity_prime in graph[node].items():
                    graph[node][nxt] = min(capacity_prime, capacity)
                    capacity_prime -= graph[node][nxt]
                    graph[nxt][node] = capacity_prime
                    if capacity_prime > 0:
                        queue.append((nxt, capacity_prime))
            for nxt, dash_capacity in sorted(graph[node].items(), key=lambda x: -graph[node][x]):
                if capacity - graph[node][dash_capacity] >= max_flow[None] and not visited[nxt]:
                    queue.append([nxt, capacity - graph[node][dash_capacity]])
                    max_flow[nxt] = max_flow[node] + dash_capacity
        return max(max_flow[None], max_flow[None] + sum(graph[node].values()) for node in graph.keys() if node is not None)

    result = max_flow(None)
    permutations = [(i + 1, result * (i + 1)) for i in range(n)]
    return sorted(permutations, key=lambda x: x[1], reverse=True)[0][0], permutations

