from collections import defaultdict

def find_transfusions(n, v, initial, desired, tubes):
    graph = defaultdict(list)
    for x, y in tubes:
        graph[x].append(y)
        graph[y].append(x)

    def can_fill_to(dst, target):
        queue = [dst]
        used = set()
        while queue:
            current = queue.pop(0)
            if current in used:
                continue
            used.add(current)
            if desired[current] <= v:
                break
            for neighbor in graph[current]:
                if desired[current] - desired[neighbor] <= v:
                    queue.append(neighbor)
        else:
            return False
        new_target = desired[dst] - desired[dst] - desired[target]
        if new_target > v:
            return False
        if new_target <= v:
            return True
        return False

    def find_transfusions_helper(preorder):
        if preorder not in visited:
            visited.add(preorder)
            for child in graph[preorder]:
                if child is not preorder and can_fill_to(preorder, child) and len(graph) - max(len(graph[neighbor]) for neighbor in graph[preorder] if neighbor != child) <= len(used):
                    yield from find_transfusions_helper(child)
                    yield preorder, child, desired[preorder] - desired[child]
            used.add(preorder)
            if preorder != 1 and can_fill_to(preorder, 1):
                yield preorder, 1, v - desired[1]
        else:
            yield preorder, 1, v - desired[1]

    preorder = 1
    used = set()
    k = 0
    for _, _, transfusion in find_transfusions_helper(preorder):
        k += 1
        if k > 2 * n * 2:
            return -1
    if k > 2 * n * 2:
        return -1
    result = []
    for x, y, d in find_transfusions_helper(preorder):
        result.append(f"{k} {x} {y} {d}")
        k += 1
    if k > 2 * n * 2:
        return -1
    if k == len(tubes) // 2 + 1:
        if min(*map((lambda x: x[2]), tubes)) + max(*map((lambda x: x[2]), tubes)) <= 2 * v:
            return "\n".join(result)
        else:
            return -1
    return -1
