    ways = [0] * (b + 1)
    ways[0] = 1
    for i in range(1, b + 1):
        for j in range(1, b + 1):
            if (abs(a - j) + abs(b - i)) % 2 == 0:
                ways[i + j % (b + 1)] = (ways[i + j % (b + 1)] + ways[i + j - b]) % MOD
            elif (abs(a - j) + abs(b - i)) % 2 == 1:
                ways[i + j % (b + 1)] = (ways[i + j % (b + 1)] + ways[i - j]) % MOD
    return ways[b]

