def can_transform(s, t):
    if len(s) < len(t):
        return 0
    s = ' ' + s
    t = ' ' + t
    dp = [[False for _ in range(len(s))] for _ in range(len(s))]

    for i in range(len(s) - len(t) + 1):
        for j in range(len(t)):
            if s[i + j] == t[j]:
                dp[i][i + len(t) - j] = dp[i + 1][i + len(t) - j + 1]

    for i in range(len(s) - len(t) + 1):
        for j in range(len(t) - 1):
            if dp[i][i + len(t) - 1] and s[i + j+1] != t[j + 1]:
                dp[i][i + len(t) - 2 - j] = True
                break

    for j in range(len(t)):
        if t[j] == s[1]:
            return dp[1][j]
    return dp[1][len(t) - 1]

