    # Find candidates for portals
    candidates = []
    for i in range(n):
        for col, cval in enumerate(c):
            if r[i] != cval:
                candidates.append((r[i]-1, col, r[i]-1, cval))

    # Maximize the number of portals to solve the problem
    portals = []
    for col in range(n):
        if any((r[i],col) in portals for i in range(n)):
            continue
        for row in range(n):
            if (col, row) in candidates:
                candidates.remove((col, row))
                portals.append((row, row, col, col))
                break

    return len(portals)

