def convert_to_tuple(a, b, c, x, y, z):
    cnt = [(0, 0, 0)] * 3
    for i in range(3):
        while a[i] >= x[i]:
            a[i] -= x[i]
            cnt[i] += (a[i],)
        while c[i] >= z[i]:
            c[i] -= z[i]
            cnt[i] += (c[i],)

    cost = 0
    for i in range(3):
        if a[i] > 0 or c[i] > 0:
            cost, a[i], c[i] = cost + 1, -1, 0
        elif a[i] < 0 and c[i] < 0:
            cost, a[i], c[i] = cost + 1, 1, 0

    cost, b[0], b[1], b[2] = cost + 1, a[0] + b[0], a[1] + b[1], a[2] + b[2]
