from collections import defaultdict

def min_broom_size(n, edges):
    graph = defaultdict(lambda: defaultdict(int))
    in_degree = [0] * (n + 1)
    for u, v, letter in edges:
        graph[u][letter] += 1
        graph[v][letter] += 1
        in_degree[v] += 1

    min_size = n
    path_size = [float('inf')] * (n + 1)
    path_size[1] = 1
    for letter in 'abcdefghijklmnopqrstuvwxyz':
        if in_degree[1] >= 2:
            break
        paths = defaultdict(list)
        for node in range(1, n + 1):
            if graph[node][letter] >= 1 and in_degree[node] <= 2:
                paths[in_degree[node] * 2].append(node)
            if graph[node][letter] >= 2 and in_degree[node] == 1:
                paths[2].append(node)
        visited = set()
        def dfs(node, depth):
            if node in visited:
                return
            if path_size[node] < float('inf') and depth > path_size[node]:
                path['min'] = min(path['min'], strand)
                path['res'] = node
            visited.add(node)
            paths[depth * 2].sort()
            for next_node in reversed(paths[depth * 2][:3]):
                if next_node not in visited:
                    dfs(next_node, depth + 1)
            visited.remove(node)
        for depth in range(3):
            path = {'min': float('inf'), 'res': None}
            dfs(path['res'], depth)
    assert path['min'] < float('inf')
    return path['min']

