def possible_sub(s, t, start_a, end_a, start_b, end_b, start_c, end_c):
    all_transitions = [(s[0:end_a], s[start_a-1], s[end_a:end_b]), 
                       (s[start_b-1], s[0], s[end_b-1]), 
                       (s[0:end_c], s[start_c], s[end_c:])]

    trans_set = set()
    for word, shift_a, shift_b in all_transitions:
        if word[shift_a] == t[shift_b] and shift_a < len(word) and shift_b < len(t):
            trans_set.add((word, shift_a, shift_b))
        if word[:-1] == s and shift_a < len(word) - 1 and shift_b < len(t):
            trans_set.add((word[:-1], shift_a, shift_b))
            trans_set.add((word[:-1][-1], shift_a, shift_b))

    if not trans_set:
        return 0
    for trans in sorted(trans_set, key=lambda t: -len(t[0])):
        if trans[0] == t[trans[2] - 1:trans[2]]:
            return 1
        elif t[:trans[2]] in (s[:trans[1] + 1] for s, sa, _ in trans_set
                              if s[:trans[1] + 1] == s):
            return 1

    if s[:end_a+1] == t[:start_c + t[0]]:
        return 1
    return 0

