def max_proper_triples(n, a):
    triple_count = defaultdict(int)
    for num in a:
        if num != 0:
            triple_count[num] += 1

    max_triples = 0
    current_sum = 0
    for num, count in sorted(triple_count.items()):
        if count > current_sum:
            max_triples += (count - current_sum) * 1/2
            current_sum = count

    max_triples *= n
    return int(max_triples)

