```python
def find_median(N, S, K, m, M):
    current_elements = []
    for i in range(N):
        if sum(current_elements) + i <= S:
            current_elements.append(i + 1)
        else:
            break
    # Find the two middle elements
    left, right = sorted(current_elements)[K-1], sorted(current_elements)[K]
    if K % 2 != 0:
        return (left + right) / 2
    else:
        return (left + right) / 2
```

