from itertools import combinations

def calculate_ways(N):
    mod = 1000000007
    dp = [0] * (N + 1)
    dp[0] = 1
    for k in range(2, N + 1):
        dp[k] = 2 * dp[k-1]
    return (dp[N] - 1) % mod

def calculate_sum_of_ways(t, N, K):
    mod = 1000000007
    ans = 0
    for comb in combinations(range(1, N + 1), N):
        a, b = sum(comb[: (K - 1)]), sum(comb[(K - 1):])
        ways = 0
        for x in [a, K + a, K - b, a + x, K + x]:
            for y in [b, K + b, K - a, b + y, K + y]:
                if x <= K and y <= N:
                    ways += dp[N - y + 1]
        ans = (ans + ways) % mod
    return ans

