MOD = 1000000007

def catalan_number(n):
    if n == 0 or n == 1:
        return 1
    else:
        return (1 + 2 * n) * catalan_number(n - 1) % MOD

T = int(input())
for _ in range(T):
    N, K = map(int, input().split())
    total_ways = 0

    for i in range(1, N + 1):
        # Number of ways starting from point (0, i)
        ways_to_AB = catalan_number(i)
        if abs(i - K) % 2 == 0:
            ways_to_AB *= 2 * N
        else:
            ways_to_AB *= 4 * N - 2 * N
        total_ways += ways_to_AB % MOD

    print(total_ways % MOD)
